      o.frequency.setValueAtTime(f1,t+d0);o.frequency.exponentialRampToValueAtTime(f2,t+d0+dur);
      lfo.frequency.setValueAtTime(vibHz,t+d0);lfoG.gain.setValueAtTime(vibAmt,t+d0);
