      _v('sawtooth',600,1200,300,0.02,0.08,0.1,0.12);
      _v('square',1500,500,0,0.05,0,0.06,0.08);
      _vib('sine',1800,900,0.05,0.2,25,120); // metallic ring with fast vibrato
      _noise(0.06,0.04); // impact noise
