var _ngMaxLen=11;
function _ngDH(s){var h1=0x811c9dc5,h2=5381,i,c;s=s.toLowerCase();for(i=0;i<s.length;i++){c=s.charCodeAt(i);h1^=c;h1=Math.imul(h1,0x01000193);h2=Math.imul(h2,33)+c;}return(h1>>>0).toString(36)+(h2>>>0).toString(36);}
function ngCheck(name){if(!name)return false;var n=name.toLowerCase();for(var l=1;l<=Math.min(n.length,_ngMaxLen);l++){for(var s=0;s+l<=n.length;s++){if(_ngH.has(_ngDH(n.substring(s,s+l))))return true;}}return false;}

